-- ----- fragment: minion_isaiah_13.sql (Isaiah 13) -----
-- Chapter: Isaiah 13 — THE BURDEN OF BABYLON / THE DAY OF YAHUAH. The oracle opens the cycle of
-- burdens against the nations. A banner is lifted, the sanctified ones mustered (13:2-3), and the
-- prophet hears *a tumultuous noise of the kingdoms of nations gathered together: Yahuah Tseva'ot
-- (LORD of hosts) mustereth the host of the battle* (13:4). The near-historical word — Babylon
-- toppled by the Medes (13:17) — is written in the language of THE DAY OF YAHUAH, the great
-- end-of-days reckoning: *the day of Yahuah (LORD) is at hand; it shall come as a destruction from
-- the Almighty* (13:6), the heavens shaken and the lights darkened (13:10,13), the proud world
-- punished (13:11), and Babylon herself made *as when Elohim (God) overthrew Sodom and Gomorrah*
-- (13:19) — the standing type of the proud city judged, whose fall the whole library carries forward
-- to *Babylon the great is fallen, is fallen* (Revelation 18:2). Judgment here is on CONDUCT —
-- arrogancy, evil, the haughtiness of the terrible — never ethnic; the Day falls on a proud WORLD.
-- Tag: isa13   Temp view: _s303_isa13_lookup
-- Sort band: base 26300, step 3 -> threads at 26300, 26303, 26306, 26309 (4 threads)
-- Source of EVERY row: 'canon','isaiah',13,v
--
-- Isaiah 13 coverage:
--   v.1-5 (the burden... a banner upon the high mountain... Yahuah Tseva'ot mustereth the host of the
--          battle... to destroy the whole land)
--        NT:     none warranted distinct (the mustered host is the preface to the Day-of-Yahuah threads)
--        Extras: none warranted
--        Tanakh: woven into THREAD 1 (the day at hand) in prose; Jeremiah 51 (the Medes against Babylon)
--                carried laterally in THREAD 4's prose
--   ★ v.6,9 (Howl ye; for the day of Yahuah is at hand... Behold, the day of Yahuah cometh, cruel
--          both with wrath and fierce anger)
--        NT:     ★ 1 Thessalonians 5:2 (the day of Yahuah so cometh as a thief in the night) — THREAD 1
--        Extras: none warranted
--        Tanakh: ★ Joel 2:1 (the day of Yahuah cometh, for it is nigh at hand), Joel 2:11 (the day of
--                Yahuah is great and very terrible; and who can abide it?), Zephaniah 1:14 (The great day
--                of Yahuah is near), Zephaniah 1:15 (a day of wrath, a day of trouble and distress) — THREAD 1
--   ★★ v.10 (the stars of heaven and the constellations thereof shall not give their light: the sun
--          shall be darkened... and the moon shall not cause her light to shine)
--        NT:     ★★ Matthew 24:29 (the sun be darkened, and the moon shall not give her light, and the
--                stars shall fall from heaven), ★★ Revelation 6:12 (the sun became black as sackcloth of
--                hair, and the moon became as blood), Revelation 6:13 (the stars of heaven fell unto the
--                earth) — THREAD 2
--        Extras: none warranted
--        Tanakh: ★ Joel 2:10 (the sun and the moon shall be dark, and the stars shall withdraw their
--                shining), Joel 2:31 (The sun shall be turned into darkness, and the moon into blood) — THREAD 2
--   ★ v.11 (I will punish the world for their evil, and the wicked for their iniquity; and I will cause
--          the arrogancy of the proud to cease)
--        NT:     none warranted distinct (the proud-world judgment is a Tanakh-lateral weave; the Day's
--                NT weight is carried in THREAD 1 and THREAD 2)
--        Extras: none warranted
--        Tanakh: ★ Isaiah 2:11 (The lofty looks of man shall be humbled... and Yahuah alone shall be
--                exalted in that day), Isaiah 2:12 (the day of Yahuah Tseva'ot shall be upon every one
--                that is proud and lofty), Isaiah 2:17 (the loftiness of man shall be bowed down... and
--                Yahuah alone shall be exalted) — THREAD 3
--   v.12-18 (I will make a man more precious than fine gold... I will shake the heavens... I will stir
--          up the Medes against them)
--        NT:     none warranted distinct (the shaking of the heavens is woven into THREAD 2's prose; the
--                Medes are the historical agent carried into THREAD 4)
--        Extras: none warranted
--        Tanakh: v.13 (I will shake the heavens) woven into THREAD 2; v.17 (the Medes) into THREAD 4 prose
--   ★ v.19 (And Babylon, the glory of kingdoms, the beauty of the Chaldees' excellency, shall be as
--          when Elohim overthrew Sodom and Gomorrah)
--        NT:     ★★ Revelation 18:2 (Babylon the great is fallen, is fallen), ★ Revelation 14:8 (Babylon
--                is fallen, is fallen, that great city) — THREAD 4
--        Extras: none warranted
--        Tanakh: ★ Genesis 19:24 (Yahuah rained upon Sodom and upon Gomorrah brimstone and fire),
--                Genesis 19:25 (he overthrew those cities), ★ Jeremiah 51:8 (Babylon is suddenly fallen
--                and destroyed) — THREAD 4
--   v.20-22 (It shall never be inhabited... wild beasts of the desert shall lie there... her time is near
--          to come) — the perpetual desolation; woven into THREAD 4 prose (the Sodom-pattern desolation)
--
-- Threads (slug — target libraries):
--   1. isaiah-13-the-day-of-yahuah-is-at-hand — NT (1 Thessalonians 5) + Tanakh (Joel 2, Zephaniah 1) [free]
--      (★ THE DAY OF YAHUAH — the great reckoning, near and terrible, coming as a thief)
--   2. isaiah-13-the-sun-darkened-and-the-stars-shall-fall — NT (Matthew 24, Revelation 6) + Tanakh (Joel 2) [free]
--      (★★ THE COSMIC SIGNS — the heavens shaken, sun/moon/stars darkened at the Day of Yahuah)
--   3. isaiah-13-i-will-punish-the-world-for-their-evil — Tanakh (Isaiah 2) [free]
--      (★ judgment of the proud WORLD — arrogancy laid low, Yahuah alone exalted; CONDUCT not ethnic)
--   4. isaiah-13-babylon-as-when-elohim-overthrew-sodom — NT (Revelation 18, Revelation 14) + Tanakh (Genesis 19, Jeremiah 51) [free]
--      (★ BABYLON FALLEN — the proud city overthrown like Sodom; the standing type, fallen, is fallen)
--
-- Framing notes:
--   ★ THE DAY OF YAHUAH (THREAD 1): *Howl ye; for the day of Yahuah (LORD) is at hand; it shall come as
--      a destruction from the Almighty* (13:6); *Behold, the day of Yahuah (LORD) cometh, cruel both with
--      wrath and fierce anger* (13:9). The burden of Babylon is written in the canon's great Day-of-Yahuah
--      vocabulary, ONE reckoning the prophets and apostles speak with one voice: *the day of Yahuah (LORD)
--      cometh, for it is nigh at hand* (Joel 2:1); *the day of Yahuah (LORD) is great and very terrible;
--      and who can abide it?* (Joel 2:11); *The great day of Yahuah (LORD) is near, it is near* (Zephaniah
--      1:14), *a day of wrath, a day of trouble and distress* (Zephaniah 1:15); and Paul: *the day of
--      Yahuah (Lord) so cometh as a thief in the night* (1 Thessalonians 5:2). The historical fall of
--      Babylon is the near rehearsal of the final Day.
--   ★★ THE COSMIC SIGNS (THREAD 2): *For the stars of heaven and the constellations thereof shall not
--      give their light: the sun shall be darkened in his going forth, and the moon shall not cause her
--      light to shine* (13:10); *Therefore I will shake the heavens* (13:13). This is the heavens-shaken
--      sign of the Day, repeated across the library word for word: *the sun and the moon shall be dark,
--      and the stars shall withdraw their shining* (Joel 2:10), *The sun shall be turned into darkness,
--      and the moon into blood* (Joel 2:31); *the sun be darkened, and the moon shall not give her light,
--      and the stars shall fall from heaven* (Matthew 24:29); *the sun became black as sackcloth of hair,
--      and the moon became as blood* (Revelation 6:12), *And the stars of heaven fell unto the earth*
--      (Revelation 6:13). The same darkening, the same shaken heavens — Isaiah's Babylon-Day is the
--      pattern Yahusha and the Revelation seal carry to the end.
--   ★ THE PROUD WORLD PUNISHED (THREAD 3): *And I will punish the world for their evil, and the wicked
--      for their iniquity; and I will cause the arrogancy of the proud to cease, and will lay low the
--      haughtiness of the terrible* (13:11). The Day falls on CONDUCT — evil, iniquity, arrogancy — never
--      on a people for their blood. Isaiah's own earlier Day-word says it twice over: *The lofty looks of
--      man shall be humbled... and Yahuah (LORD) alone shall be exalted in that day* (Isaiah 2:11); *For
--      the day of Yahuah Tseva'ot (LORD of hosts) shall be upon every one that is proud and lofty* (Isaiah
--      2:12); *the loftiness of man shall be bowed down... and Yahuah (LORD) alone shall be exalted in
--      that day* (Isaiah 2:17). The whole proud world is brought low that Yahuah alone be exalted.
--   ★ BABYLON FALLEN (THREAD 4): *And Babylon, the glory of kingdoms, the beauty of the Chaldees'
--      excellency, shall be as when Elohim (God) overthrew Sodom and Gomorrah* (13:19), made a perpetual
--      desolation never inhabited (13:20-22). Babylon's judgment is measured by the oldest pattern of the
--      proud city overthrown: *Then Yahuah (LORD) rained upon Sodom and upon Gomorrah brimstone and fire
--      from Yahuah (LORD) out of heaven* (Genesis 19:24), *And he overthrew those cities, and all the
--      plain* (Genesis 19:25). Jeremiah's parallel burden seals it: *Babylon is suddenly fallen and
--      destroyed* (Jeremiah 51:8). And the library carries Babylon forward as the standing type of every
--      proud, fornicating world-system judged: *Babylon the great is fallen, is fallen* (Revelation 18:2);
--      *Babylon is fallen, is fallen, that great city* (Revelation 14:8). The Chaldean city is the first
--      member of a name that runs to the end.
--   VERSES WITH NO SEPARATE ADD: v.1-5 (the mustered host — preface to THREAD 1), v.7-8 (faint hands,
--      melting hearts — the terror of the Day, woven into THREAD 1), v.12 (a man more precious than gold —
--      the scarcity of survivors, the lawsuit-judgment held in prose), v.13 (I will shake the heavens —
--      woven into THREAD 2), v.14-18 (the slaughter, the Medes — historical agency, carried into THREAD 4),
--      v.20-22 (the perpetual desolation — the Sodom-pattern aftermath, woven into THREAD 4). All recorded,
--      none silently skipped.

CREATE TEMP VIEW _s303_isa13_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id=c.id JOIN books b ON c.book_id=b.id
  JOIN editions e ON b.edition_id=e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM (VALUES
    -- THREAD 1 (★): The day of Yahuah is at hand — the great reckoning, near and terrible
    ('canon','isaiah',13,6,'canon','joel',2,1,'free',
      E'*Blow ye the trumpet in Zion, and sound an alarm in my holy mountain: let all the inhabitants of the land tremble: for the day of Yahuah (LORD) cometh, for it is nigh at hand* (Joel 2:1). Isaiah''s cry *Howl ye; for the day of Yahuah (LORD) is at hand; it shall come as a destruction from the Almighty* (Isaiah 13:6) is the very Day Joel sounds the alarm for — *the day of Yahuah (LORD) cometh, for it is nigh at hand*. One reckoning, near and terrible, announced by trumpet and by howling.'),
    ('canon','isaiah',13,9,'canon','joel',2,11,'free',
      E'*And Yahuah (LORD) shall utter his voice before his army: for his camp is very great: for he is strong that executeth his word: for the day of Yahuah (LORD) is great and very terrible; and who can abide it?* (Joel 2:11). The Day that comes *cruel both with wrath and fierce anger, to lay the land desolate* (Isaiah 13:9) is the Day Joel calls *great and very terrible* — and asks *who can abide it?* The same dreadful reckoning, before which all hands are faint and every heart melts (13:7).'),
    ('canon','isaiah',13,6,'canon','zephaniah',1,14,'free',
      E'*The great day of Yahuah (LORD) is near, it is near, and hasteth greatly, even the voice of the day of Yahuah (LORD): the mighty man shall cry there bitterly* (Zephaniah 1:14). Isaiah''s *the day of Yahuah (LORD) is at hand* (Isaiah 13:6) is Zephaniah''s *great day of Yahuah (LORD)* that *is near, it is near, and hasteth greatly* — the same imminent Day, when even the mighty man cries bitterly.'),
    ('canon','isaiah',13,9,'canon','zephaniah',1,15,'free',
      E'*That day is a day of wrath, a day of trouble and distress, a day of wasteness and desolation, a day of darkness and gloominess, a day of clouds and thick darkness* (Zephaniah 1:15). The Day that comes *cruel both with wrath and fierce anger, to lay the land desolate* (Isaiah 13:9) is Zephaniah''s *day of wrath... a day of wasteness and desolation* — the identical Day of Yahuah, wrath and desolation together.'),
    ('canon','isaiah',13,6,'canon','1-thessalonians',5,2,'free',
      E'*For yourselves know perfectly that the day of Yahuah (Lord) so cometh as a thief in the night* (1 Thessalonians 5:2). The Day Isaiah says is *at hand* (Isaiah 13:6) is the Day Paul says *cometh as a thief in the night* — the same Day of Yahuah, sudden and unescapable: *when they shall say, Peace and safety; then sudden destruction cometh upon them* (5:3). The prophet''s burden and the apostle''s warning name one Day.'),

    -- THREAD 2 (★★): The sun darkened and the stars shall fall — the cosmic signs of the Day
    ('canon','isaiah',13,10,'canon','matthew',24,29,'free',
      E'*Immediately after the tribulation of those days shall the sun be darkened, and the moon shall not give her light, and the stars shall fall from heaven, and the powers of the heavens shall be shaken* (Matthew 24:29). Yahusha (Jesus) speaks Isaiah''s Babylon-Day sign word for word: *the sun shall be darkened in his going forth, and the moon shall not cause her light to shine* (Isaiah 13:10), and *the stars of heaven and the constellations thereof shall not give their light*. The darkened sun, the lightless moon, the falling stars, the shaken heavens (Isaiah 13:13) — one sign of the one Day, the prophet''s pattern carried to the end.'),
    ('canon','isaiah',13,10,'canon','revelation',6,12,'free',
      E'*And I beheld when he had opened the sixth seal, and, lo, there was a great earthquake; and the sun became black as sackcloth of hair, and the moon became as blood* (Revelation 6:12). The sixth-seal sign is Isaiah''s Day-of-Yahuah sign: *the sun shall be darkened... and the moon shall not cause her light to shine* (Isaiah 13:10). The sun made black, the moon turned to blood — *the great day of his wrath is come; and who shall be able to stand?* (6:17) — the cosmic upheaval Isaiah saw over Babylon.'),
    ('canon','isaiah',13,10,'canon','revelation',6,13,'free',
      E'*And the stars of heaven fell unto the earth, even as a fig tree casteth her untimely figs, when she is shaken of a mighty wind* (Revelation 6:13). Isaiah''s *stars of heaven and the constellations thereof shall not give their light* (Isaiah 13:10) becomes, at the sixth seal, *the stars of heaven fell unto the earth*. The heavens are shaken (Isaiah 13:13); the lights of the firmament fail at the day of Yahuah''s wrath.'),
    ('canon','isaiah',13,10,'canon','joel',2,10,'free',
      E'*The earth shall quake before them; the heavens shall tremble: the sun and the moon shall be dark, and the stars shall withdraw their shining* (Joel 2:10). Joel speaks the same sign as Isaiah''s Day: *the sun shall be darkened... and the moon shall not cause her light to shine* (Isaiah 13:10). *The sun and the moon shall be dark, and the stars shall withdraw their shining* — the heavens trembling, the lights failing, before the great and terrible Day.'),
    ('canon','isaiah',13,10,'canon','joel',2,31,'free',
      E'*The sun shall be turned into darkness, and the moon into blood, before the great and the terrible day of Yahuah (LORD) come* (Joel 2:31). Isaiah''s darkened sun and lightless moon (Isaiah 13:10) are Joel''s *sun... turned into darkness, and the moon into blood* — and Joel names the occasion plainly: it is *before the great and the terrible day of Yahuah (LORD) come*. The cosmic signs are the heralds of the one Day.'),

    -- THREAD 3 (★): I will punish the world for their evil — the proud WORLD judged (conduct, not ethnic)
    ('canon','isaiah',13,11,'canon','isaiah',2,11,'free',
      E'*The lofty looks of man shall be humbled, and the haughtiness of men shall be bowed down, and Yahuah (LORD) alone shall be exalted in that day* (Isaiah 2:11). The Day that *will punish the world for their evil... and lay low the haughtiness of the terrible* (Isaiah 13:11) is Isaiah''s earlier Day-word: *the haughtiness of men shall be bowed down, and Yahuah (LORD) alone shall be exalted*. The arrogancy of the proud is brought low that Yahuah alone be exalted — judgment on pride, never on a people.'),
    ('canon','isaiah',13,11,'canon','isaiah',2,12,'free',
      E'*For the day of Yahuah Tseva''ot (LORD of hosts) shall be upon every one that is proud and lofty, and upon every one that is lifted up; and he shall be brought low* (Isaiah 2:12). Isaiah 13:11 — *I will cause the arrogancy of the proud to cease* — is the same verdict: *the day of Yahuah Tseva''ot (LORD of hosts) shall be upon every one that is proud and lofty... and he shall be brought low*. The Day targets conduct — pride and arrogancy — wherever it is found.'),
    ('canon','isaiah',13,11,'canon','isaiah',2,17,'free',
      E'*And the loftiness of man shall be bowed down, and the haughtiness of men shall be made low: and Yahuah (LORD) alone shall be exalted in that day* (Isaiah 2:17). The punishing of *the world for their evil, and the wicked for their iniquity* (Isaiah 13:11) ends where Isaiah''s Day-word ends: *Yahuah (LORD) alone shall be exalted in that day*. The whole proud world is humbled so that the exalting belongs to Yahuah alone.'),

    -- THREAD 4 (★): Babylon as when Elohim overthrew Sodom — the proud city fallen, fallen
    ('canon','isaiah',13,19,'canon','genesis',19,24,'free',
      E'*Then Yahuah (LORD) rained upon Sodom and upon Gomorrah brimstone and fire from Yahuah (LORD) out of heaven* (Genesis 19:24). Isaiah measures Babylon''s fall by the oldest overthrow: *Babylon, the glory of kingdoms... shall be as when Elohim (God) overthrew Sodom and Gomorrah* (Isaiah 13:19). The brimstone and fire that fell on Sodom is the pattern of the proud city judged — Babylon shall be as Sodom was.'),
    ('canon','isaiah',13,19,'canon','genesis',19,25,'free',
      E'*And he overthrew those cities, and all the plain, and all the inhabitants of the cities, and that which grew upon the ground* (Genesis 19:25). The Sodom-overthrow Isaiah invokes — *as when Elohim (God) overthrew Sodom and Gomorrah* (Isaiah 13:19) — is the total ruin of *those cities, and all the plain*. So Babylon: *It shall never be inhabited... from generation to generation* (Isaiah 13:20), a perpetual desolation like the overthrown plain.'),
    ('canon','isaiah',13,19,'canon','jeremiah',51,8,'free',
      E'*Babylon is suddenly fallen and destroyed: howl for her; take balm for her pain, if so be she may be healed* (Jeremiah 51:8). Jeremiah''s parallel burden against Babylon sounds Isaiah''s verdict — *Babylon, the glory of kingdoms... shall be as when Elohim (God) overthrew Sodom and Gomorrah* (Isaiah 13:19) — in the very cry Isaiah opened with: *Howl ye* (13:6). *Babylon is suddenly fallen and destroyed* — the same proud city, the same sudden ruin.'),
    ('canon','isaiah',13,19,'canon','revelation',18,2,'free',
      E'*And he cried mightily with a strong voice, saying, Babylon the great is fallen, is fallen, and is become the habitation of devils, and the hold of every foul spirit, and a cage of every unclean and hateful bird* (Revelation 18:2). The fall Isaiah pronounced on the Chaldean city — *as when Elohim (God) overthrew Sodom and Gomorrah* (Isaiah 13:19) — runs to the end of the library as *Babylon the great is fallen, is fallen*. Isaiah''s desolate Babylon, where *wild beasts of the desert shall lie* (13:21), becomes *the habitation of devils... a cage of every unclean and hateful bird*. The standing type of the proud world-system, judged.'),
    ('canon','isaiah',13,19,'canon','revelation',14,8,'free',
      E'*And there followed another angel, saying, Babylon is fallen, is fallen, that great city, because she made all nations drink of the wine of the wrath of her fornication* (Revelation 14:8). The first angel''s cry carries Isaiah''s Babylon-burden forward — *Babylon, the glory of kingdoms... shall be as when Elohim (God) overthrew Sodom and Gomorrah* (Isaiah 13:19) — to *Babylon is fallen, is fallen, that great city*. The proud city of the Chaldees is the first member of a name the whole canon judges to its end.')
  ) AS i(src_edition,src_slug,src_ch,src_v,tgt_edition,tgt_slug,tgt_ch,tgt_v,tier,note)
  JOIN _s303_isa13_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s303_isa13_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- THREAD 1 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-13-the-day-of-yahuah-is-at-hand',
       E'The day of Yahuah is at hand — the great reckoning, near and terrible',
       E'The burden of Babylon is written in the canon''s great Day-of-Yahuah vocabulary: *Howl ye; for the day of Yahuah (LORD) is at hand; it shall come as a destruction from the Almighty* (Isaiah 13:6), and *Behold, the day of Yahuah (LORD) cometh, cruel both with wrath and fierce anger, to lay the land desolate: and he shall destroy the sinners thereof out of it* (13:9). Before it *all hands be faint, and every man''s heart shall melt* (13:7). This is no merely local word — it is the one reckoning the prophets and the apostle name with a single voice. Joel sounds the alarm for it: *Blow ye the trumpet in Zion... for the day of Yahuah (LORD) cometh, for it is nigh at hand* (Joel 2:1), *the day of Yahuah (LORD) is great and very terrible; and who can abide it?* (Joel 2:11). Zephaniah hastens it: *The great day of Yahuah (LORD) is near, it is near, and hasteth greatly* (Zephaniah 1:14), *a day of wrath, a day of trouble and distress, a day of wasteness and desolation* (Zephaniah 1:15). And Paul carries it to the assembly: *the day of Yahuah (Lord) so cometh as a thief in the night* (1 Thessalonians 5:2) — *when they shall say, Peace and safety; then sudden destruction cometh upon them* (5:3). The historical fall of Babylon to the Medes is the near rehearsal of the final Day of Yahuah, at hand and terrible.',
       sv.verse_id, ev.verse_id, 'free', 26300
  FROM _s303_isa13_lookup sv, _s303_isa13_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=13 AND sv.verse_number=6
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=13 AND ev.verse_number=9
ON CONFLICT (slug) DO NOTHING;

-- THREAD 2 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-13-the-sun-darkened-and-the-stars-shall-fall',
       E'The sun darkened and the stars shall fall — the cosmic signs of the Day',
       E'The Day of Yahuah shakes the very heavens: *For the stars of heaven and the constellations thereof shall not give their light: the sun shall be darkened in his going forth, and the moon shall not cause her light to shine* (Isaiah 13:10); *Therefore I will shake the heavens, and the earth shall remove out of her place, in the wrath of Yahuah Tseva''ot (LORD of hosts)* (13:13). This darkening of sun, moon, and stars is the canon''s standing sign of the Day, sounded across the whole library in the same words. Joel: *The earth shall quake before them; the heavens shall tremble: the sun and the moon shall be dark, and the stars shall withdraw their shining* (Joel 2:10), *The sun shall be turned into darkness, and the moon into blood, before the great and the terrible day of Yahuah (LORD) come* (Joel 2:31). Yahusha (Jesus) speaks it over the end: *Immediately after the tribulation of those days shall the sun be darkened, and the moon shall not give her light, and the stars shall fall from heaven, and the powers of the heavens shall be shaken* (Matthew 24:29). And the sixth seal enacts it: *the sun became black as sackcloth of hair, and the moon became as blood* (Revelation 6:12), *And the stars of heaven fell unto the earth, even as a fig tree casteth her untimely figs* (Revelation 6:13). One sign, one shaken heaven, one Day — Isaiah''s burden over Babylon is the pattern carried to the consummation.',
       sv.verse_id, ev.verse_id, 'free', 26303
  FROM _s303_isa13_lookup sv, _s303_isa13_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=13 AND sv.verse_number=10
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=13 AND ev.verse_number=13
ON CONFLICT (slug) DO NOTHING;

-- THREAD 3 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-13-i-will-punish-the-world-for-their-evil',
       E'I will punish the world for their evil — the proud world brought low',
       E'The Day falls on conduct, not on blood: *And I will punish the world for their evil, and the wicked for their iniquity; and I will cause the arrogancy of the proud to cease, and will lay low the haughtiness of the terrible* (Isaiah 13:11). The charge is evil, iniquity, arrogancy, haughtiness — a moral reckoning on a proud WORLD, never an ethnic verdict. Isaiah''s own earlier Day-word frames it exactly, and twice declares its end: *The lofty looks of man shall be humbled, and the haughtiness of men shall be bowed down, and Yahuah (LORD) alone shall be exalted in that day* (Isaiah 2:11); *For the day of Yahuah Tseva''ot (LORD of hosts) shall be upon every one that is proud and lofty, and upon every one that is lifted up; and he shall be brought low* (Isaiah 2:12); *And the loftiness of man shall be bowed down, and the haughtiness of men shall be made low: and Yahuah (LORD) alone shall be exalted in that day* (Isaiah 2:17). The arrogancy of the proud is silenced so that the exalting belongs to Yahuah alone. The Day of Yahuah is the great leveling of human pride before the one who alone is high and lifted up.',
       sv.verse_id, ev.verse_id, 'free', 26306
  FROM _s303_isa13_lookup sv, _s303_isa13_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=13 AND sv.verse_number=11
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=13 AND ev.verse_number=11
ON CONFLICT (slug) DO NOTHING;

-- THREAD 4 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-13-babylon-as-when-elohim-overthrew-sodom',
       E'Babylon as when Elohim overthrew Sodom — the proud city fallen, fallen',
       E'The oracle names Babylon''s end by the oldest overthrow in the canon: *And Babylon, the glory of kingdoms, the beauty of the Chaldees'' excellency, shall be as when Elohim (God) overthrew Sodom and Gomorrah* (Isaiah 13:19) — *It shall never be inhabited, neither shall it be dwelt in from generation to generation* (13:20), left to wild beasts and dragons (13:21-22). The Sodom-pattern is the brimstone-and-fire judgment of the proud city: *Then Yahuah (LORD) rained upon Sodom and upon Gomorrah brimstone and fire from Yahuah (LORD) out of heaven* (Genesis 19:24), *And he overthrew those cities, and all the plain* (Genesis 19:25). Jeremiah''s parallel burden seals the same verdict in Isaiah''s own opening cry — *Howl ye* (13:6): *Babylon is suddenly fallen and destroyed: howl for her* (Jeremiah 51:8). And the whole library carries Babylon forward as the standing type of every proud, fornicating world-system judged: *Babylon is fallen, is fallen, that great city* (Revelation 14:8); *Babylon the great is fallen, is fallen, and is become the habitation of devils, and the hold of every foul spirit, and a cage of every unclean and hateful bird* (Revelation 18:2) — Isaiah''s desolate Babylon, *full of doleful creatures* (13:21), seen to the end. The Chaldean city is the first member of a name the canon judges from Sodom to the final Day.',
       sv.verse_id, ev.verse_id, 'free', 26309
  FROM _s303_isa13_lookup sv, _s303_isa13_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=13 AND sv.verse_number=19
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=13 AND ev.verse_number=19
ON CONFLICT (slug) DO NOTHING;

